<title><?php echo htmlspecialchars(htmlspecialchars($settings['display_name'] ?? $plugin_info['plugin_name']) ?? $plugin_info['plugin_name'])?> - <?php echo htmlspecialchars($settings['account_name'] ?? $setting['response'][0]['site_name'])?></title>
<link rel="icon" href="<?php echo isset($setting['response'][0]['favicon']) && $setting['response'][0]['favicon'] != '--' ? $setting['response'][0]['favicon'] : 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8Xw8AAoMBgDTD2qgAAAAASUVORK5CYII='?>">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><script src="https://ajax.googleapis.com/ajax/libs/jquery/3.4.1/jquery.min.js"></script>
<style>
