.pay-grid>div:first-child .section-label{order:1}.pay-grid>div:first-child .account-type{order:2}.pay-grid>div:first-child .phone{order:3}.pay-grid>div:first-child .recipient-name{order:4}.pay-grid>div:first-child .phone{justify-content:center}.pay-grid>div:first-child .recipient-name{justify-content:center}.divider{height:190px;background:var(--line);position:relative}.divider span{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:#fff;border:1px solid var(--line);border-radius:50%;padding:10px 8px;font-size:10px;font-weight:700;color:var(--pink)}.section-label,.field label{font-size:13px;color:var(--muted);font-weight:600}.recipient{display:flex;flex-direction:column;gap:8px;align-items:center;margin:15px 0 3px}.recipient strong{font-size:16px}.verified{color:#2F80ED;font-size:16px}.recipient strong,.recipient .verified{margin-top:0}.recipient-name{display:flex;align-items:center;justify-content:center;gap:6px}.account-name{color:#fff;background:#e0146d;border-radius:10px;padding:5px}.account-type{font-size:12px;color:var(--muted);margin-top:5px;margin-bottom:-2px}.recipient strong{display:inline-block}.recipient .verified{margin-left:0}.phone{position:relative;display:inline-flex;align-items:center;justify-content:center;min-width:188px;width:100%;background:transparent;border:0;border-top:0;border-bottom:0;border-radius:0;padding:12px 14px;font-size:16px;font-weight:600}.phone-number{white-space:nowrap}.phone-number strong{font-size:18px;font-weight:700}.phone>i{font-size:16px}.copy{position:static;border:0;background:none;color:var(--pink);cursor:pointer;font:600 12px Inter;padding:0;margin-left:8px}.scan{text-align:center}.scan h2{font-size:14px;color:var(--muted);font-weight:400;margin:0 0 8px}.qr-frame{position:relative;width:158px;height:158px;margin:auto;padding:4px}.qr-frame:before{content:'';position:absolute;z-index:2;inset:0;pointer-events:none;background:linear-gradient(var(--pink),var(--pink)) top left/18px 3px no-repeat,linear-gradient(var(--pink),var(--pink)) top left/3px 18px no-repeat,linear-gradient(var(--pink),var(--pink)) top right/18px 3px no-repeat,linear-gradient(var(--pink),var(--pink)) top right/3px 18px no-repeat,linear-gradient(var(--pink),var(--pink)) bottom left/18px 3px no-repeat,linear-gradient(var(--pink),var(--pink)) bottom left/3px 18px no-repeat,linear-gradient(var(--pink),var(--pink)) bottom right/18px 3px no-repeat,linear-gradient(var(--pink),var(--pink)) bottom right/3px 18px no-repeat;border-radius:0}.qr-dl{position:absolute;z-index:3;right:-14px;bottom:-14px;width:38px;height:38px;display:grid;place-items:center;border:1px solid var(--line);border-radius:50%;background:#fff;color:var(--pink);box-shadow:0 6px 16px rgba(26,26,26,.14);cursor:pointer;transition:.2s}.qr-dl:hover{background:var(--pink);border-color:var(--pink);color:#fff;transform:translateY(-1px)}.qr-dl i{font-size:15px}.qr{position:relative;z-index:1;display:block;width:150px;height:150px;padding:5px;margin:auto;border:0;border-radius:0;box-shadow:none;background:#fff}.form-area{border-top:1px solid var(--line);margin-top:30px;padding-top:26px}.field{margin-bottom:18px}.field label{display:block;margin-bottom:8px;color:var(--ink)}.input-wrap{position:relative}.input-wrap i{position:absolute;left:17px;top:50%;transform:translateY(-50%);color:#A2A6AD;font-size:15px;line-height:1;z-index:1}.input{width:100%;height:54px;border:1px solid var(--line);border-radius:15px;padding:0 18px 0 46px;line-height:54px;font:inherit;outline:0;background:#FCFCFD}.input:focus{border-color:var(--pink);box-shadow:0 0 0 4px rgba(226,19,110,.1)}.btn-pay{width:100%;height:auto;padding:15px 20px;border:0;border-radius:16px;background:linear-gradient(100deg,var(--pink),var(--pink2));color:#fff;font:700 14px Inter;cursor:pointer;box-shadow:0 10px 20px rgba(226,19,110,.2);transition:.2s}.btn-pay:hover{filter:brightness(1.08);box-shadow:0 12px 26px rgba(226,19,110,.3)}.response{display:block;margin-bottom:12px}.alert{padding:12px;border-radius:12px;font-size:13px;background:#fff0f0;color:#c0392b}.footer{text-align:center;color:#9a9da3;font-size:12px;margin-top:22px}@media(max-width:600px){.page{width:calc(100% - 16px);margin:10px auto 24px;padding:0 14px 18px}.main{padding:16px}.pay-grid{grid-template-columns:1fr;gap:16px}.divider{height:1px;width:100%}.divider span{padding:7px 10px}.scan{padding-top:0}.price{font-size:28px;letter-spacing:-1px;margin-top:2px}.amount{padding:16px 20px}.top{margin-bottom:10px;padding:12px 14px 0 !important}.form-area{margin-top:18px;padding-top:16px}.field{margin-bottom:13px}.input{height:48px;line-height:48px}.qr-frame{width:132px;height:132px}.qr{width:124px;height:124px}.recipient{margin:8px 0 3px}.phone{padding:8px 14px}.footer{margin-top:14px}}
