<body><main class="page"><header class="top" style="padding:18px 20px 0"><button class="back" onclick="location.href='<?php echo pp_get_paymentlink($payment_id)?>'" aria-label="Back"><i class="fa-solid fa-arrow-left"></i><span>Back</span></button><img src="<?php echo $logo?>" alt="bKash"><span aria-hidden="true"></span></header>
<section class="card amount"><div class="eyebrow">Amount to Pay</div><div class="price"><?php echo $amount?></div></section>
<section class="card main"><div class="pay-grid"><div><div class="recipient"><div class="section-label">Send Money To</div><div class="account-type">bKash Personal Account</div><div class="recipient-name account-name"><strong><?php echo htmlspecialchars($settings['account_name'] ?? $setting['response'][0]['site_name'])?></strong></div></div><div class="phone"><span class="phone-number recipient-name"><strong><?php echo htmlspecialchars($display_payment_number)?></strong></span></div></div><div class="divider"><span>OR</span></div><div class="scan"><h2>Scan to Pay</h2><div class="qr-frame"><img class="qr" id="pp-qr-img" src="<?php echo !empty($settings['qr_code']) ? htmlspecialchars($settings['qr_code']) : 'https://api.qrserver.com/v1/create-qr-code/?size=240x240&data='.urlencode('bKash '.$payment_number.' '.$amount); ?>" alt="Payment QR code"><button type="button" class="qr-dl" id="pp-qr-dl" aria-label="Download QR code" title="Download QR"><i class="fa-solid fa-download"></i></button></div></div></div>
<div class="form-area"><div class="field mobile-number-box" style="display:none"><label>Your bKash Number</label><div class="input-wrap"><i class="fa-solid fa-mobile-screen-button"></i><input class="input mobile-number" placeholder="01XXXXXXXXX"></div></div><div class="field"><label>Transaction ID</label><div class="input-wrap"><i class="fa-solid fa-hashtag"></i><input class="input transaction-id" placeholder="DGVXXXXX"></div></div><span class="response"></span><button class="btn-pay"><i class="fa-solid fa-shield-halved"></i>&nbsp; Verify</button></div></section><footer class="footer">Secure payment verification · Powered by <strong>KeyClan</strong></footer></main>
<script>
function copyText(text,button){if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(text).then(function(){var original=button.innerHTML;button.innerHTML='<i class="fa-solid fa-check"></i>';button.disabled=true;setTimeout(function(){button.innerHTML=original;button.disabled=false},2000)})}}
$('.btn-pay').on('click',function(){var btn=this,trxid=$('.transaction-id').val(),number=$('.mobile-number').val();if(!trxid){$('.response').text('Enter transaction ID').addClass('alert');return}btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i>';$.ajax({type:'POST',url:'<?php echo pp_get_paymentlink($payment_id)?>?method=bkash-personal',data:{'bkash-personal':'<?php echo $payment_id?>',trxid:trxid,number:number},success:function(data){btn.innerHTML='<i class="fa-solid fa-shield-halved"></i>&nbsp; Verify';var result=JSON.parse(data);if(result.status==='false'){if(result.numberbox==='true'){$('.mobile-number-box').show();$('.response').text('Enter mobile number').addClass('alert')}else $('.response').text(result.message || 'Request failed').addClass('alert')}else location.href='<?php echo pp_get_paymentlink($payment_id)?>'}})})
</script><script>(function(){var btn=document.getElementById("pp-qr-dl"),img=document.getElementById("pp-qr-img");if(!btn||!img)return;btn.addEventListener("click",async function(){if(!img.src)return;try{var r=await fetch(img.src,{mode:"cors"});var b=await r.blob();var u=URL.createObjectURL(b);var a=document.createElement("a");a.href=u;a.download="payment-qr.png";document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(u)},4000)}catch(e){var f=document.createElement("a");f.href=img.src;f.download="payment-qr.png";f.target="_blank";f.rel="noopener";document.body.appendChild(f);f.click();f.remove()}})});</script></body></html>